create table corpus_revision(id integer primary key check(id=1),version bigint not null);insert into corpus_revision values(1,1);
create table suggestions(id varchar(64) not null,tenant varchar(64) not null,text varchar(256) not null,type varchar(32) not null,category varchar(64) not null,language varchar(32) not null,active boolean not null,popularity bigint not null check(popularity>=0),boost double precision not null check(boost between 0 and 10),primary key(tenant,id));
create index suggestions_tenant on suggestions(tenant,id);
